 140 │ function findProjectRoot(startDir) {
 141 │   // Simple heuristic: find the nearest .git directory or package.json
 142 │   let current = path.resolve(startDir);
 143 │   const home = os.homedir();
 144 │   while (current.startsWith(home + path.sep) && current !== home) {
 145 │     if (fs.existsSync(path.join(current, '.git')) ||
 146 │         fs.existsSync(path.join(current, 'package.json')) ||
 147 │         fs.existsSync(path.join(current, 'AGENTS.md'))) {
 148 │       return current;
 149 │     }
 150 │     const parent = path.dirname(current);
 151 │     if (parent === current) break;
 152 │     current = parent;
 153 │   }
 154 │   return startDir;
 155 │ }
