 157 │ function loadAgentsMd(cwd) {
 158 │   if (!cwd) cwd = process.cwd();
 159 │   const projectRoot = findProjectRoot(cwd);
 160 │ 
 161 │   // Collect directories from projectRoot down to cwd
 162 │   const dirs = [];
 163 │   let current = path.resolve(cwd);
 164 │   const root = path.resolve(projectRoot);
 165 │   while (true) {
 166 │     dirs.push(current);
 167 │     if (current === root) break;
 168 │     const parent = path.dirname(current);
 169 │     if (parent === current) break;
 170 │     current = parent;
 171 │   }
 172 │   dirs.reverse(); // root -> leaf
 173 │ 
 174 │   // Phase 1: collect all candidate files (root -> leaf order)
 175 │   const discovered = [];
 176 │   for (const d of dirs) {
 177 │     // .kimi/AGENTS.md is checked independently (can coexist with root-level file)
 178 │     const kimiPath = path.join(d, '.kimi', 'AGENTS.md');
 179 │     // AGENTS.md and agents.md are mutually exclusive (uppercase wins)
 180 │     const rootCandidates = [path.join(d, 'AGENTS.md'), path.join(d, 'agents.md')];
 181 │ 
 182 │     const candidates = [];
 183 │     if (fs.existsSync(kimiPath) && fs.statSync(kimiPath).isFile()) {
 184 │       candidates.push(kimiPath);
 185 │     }
 186 │     for (const rc of rootCandidates) {
 187 │       if (fs.existsSync(rc) && fs.statSync(rc).isFile()) {
 188 │         candidates.push(rc);
 189 │         break;
 190 │       }
 191 │     }
 192 │ 
 193 │     for (const filePath of candidates) {
 194 │       try {
 195 │         const content = fs.readFileSync(filePath, 'utf8').trim();
 196 │         if (content) discovered.push({ path: filePath, content });
 197 │       } catch { /* ignore read errors */ }
 198 │     }
 199 │   }
 200 │ 
 201 │   if (!discovered.length) return null;
 202 │ 
 203 │   // Phase 2: allocate budget leaf-first so deeper files are never truncated
 204 │   let remaining = AGENTS_MD_MAX_BYTES;
 205 │   const budgeted = new Array(discovered.length).fill(null);
 206 │   for (let i = discovered.length - 1; i >= 0; i--) {
 207 │     const { path: filePath, content } = discovered[i];
 208 │     const annotation = `<!-- From: ${filePath} -->\n`;
 209 │     const separatorCost = i < discovered.length - 1 ? Buffer.byteLength('\n\n', 'utf8') : 0;
 210 │     const overhead = Buffer.byteLength(annotation, 'utf8') + separatorCost;
 211 │     remaining -= overhead;
 212 │     if (remaining <= 0) {
 213 │       budgeted[i] = { path: filePath, content: '' };
 214 │       remaining = 0;
 215 │       continue;
 216 │     }
 217 │     const encoded = Buffer.from(content, 'utf8');
 218 │     if (encoded.length > remaining) {
 219 │       const truncated = encoded.slice(0, remaining).toString('utf8').trim();
 220 │       budgeted[i] = { path: filePath, content: truncated };
 221 │       remaining = 0;
 222 │     } else {
 223 │       budgeted[i] = { path: filePath, content };
 224 │       remaining -= encoded.length;
 225 │     }
 226 │   }
 227 │ 
 228 │   // Phase 3: assemble in root -> leaf order
 229 │   const parts = [];
 230 │   for (const { path: filePath, content } of budgeted) {
 231 │     if (content) parts.push(`<!-- From: ${filePath} -->\n${content}`);
 232 │   }
 233 │   return parts.join('\n\n') || null;
 234 │ }
