 388 │   // Strategy 1: Remove markdown code blocks
 389 │   cleaned = cleaned
 390 │     .replace(/```json\s*/gi, '')
 391 │     .replace(/```\s*$/gm, '')
 392 │     .replace(/```/g, '');
