 394 │   // Strategy 1b: Unescape double-escaped JSON chars
 395 │   // FIX: Order matters! First handle \\ → \, THEN \\\" → \"
 396 │   cleaned = cleaned
 397 │     .replace(/\\\\/g, '\\')     // FIRST: \\ → \  (must be first!)
 398 │     .replace(/\\\[/g, '[')
 399 │     .replace(/\\\]/g, ']')
 400 │     .replace(/\\\{/g, '{')
 401 │     .replace(/\\\}/g, '}')
 402 │     .replace(/\\"/g, '"');       // LAST: \" → "  (after \\ → \ is done)
