 404 │   const strategies = [
 405 │     // Strategy 2: Direct parse (text already has proper JSON escapes)
 406 │     () => JSON.parse(cleaned),
 407 │     // Strategy 2b: Direct parse with real newlines escaped (DOM returns real newlines inside strings)
 408 │     () => {
 409 │       const reescaped = cleaned.replace(/("response"\s*:\s*")([\s\S]*?)("\s*[,}])/g, (match, prefix, value, suffix) => {
 410 │         const escaped = value
 411 │           .replace(/\\/g, '\\\\')
 412 │           .replace(/"/g, '\\"')
